      "id": "1",
      "type": "start",
      "param": {
        "variables": [
          ["doc_list", "array[file]"]
        ]
      }
    },
    {
      "id": "2",
      "type": "iteration",
      "param": {
        "iterator_selector": ["doc_list", "1"],
        "output_selector": ["summary", "2-4"]
      }
    },
    {
      "id": "2-1",
      "type": "iteration-start",
      "param": {}
    },
    {
      "id": "2-2",
      "type": "document-extractor",
      "param": {
        "variable_selector": ["item", "2-1"]
      }
    },
    {
      "id": "2-3",
      "type": "llm",
      "param": {
        "system": "You are an expert document analyzer. Your task is to comprehensively parse the article structure, analyze the main content and function of each part, and provide a detailed summary based on your analysis.",
        "user": "Please analyze the following document:\n\n{{#'2-2'.text#}}\n\nFirst, parse the article structure.\nThen, analyze the main content and function of each part.\nFinally, provide a comprehensive summary based on your parsing and analysis."
      }
    },
    {
      "id": "2-4",
      "type": "template-transform",
      "param": {
        "variables": [
          ["doc_summary", ["text", "2-3"]]
        ],
        "template": "{{doc_summary}}"
      }
    },
    {
      "id": "3",
      "type": "template-transform",
      "param": {
        "variables": [
          ["summaries", ["output", "2"]]
        ],
        "template": "{% for summary in summaries %}--- Document {{ loop.index }} Summary ---\n{{ summary }}\n\n{% endfor %}"
      }
    },
    {
      "id": "4",
      "type": "markdown-exporter",
      "param": {
        "target_type": "docx",
        "md_text": "# Document Analysis Summary\n\n{{#'3'.output#}}"
      }
    },
    {
      "id": "5",
      "type": "end",
      "param": {
        "outputs": [
          ["summary", ["output", "3"]],
          ["docx_file", ["files", "4"]]
        ]
      }
    }
  ],
  "edges": [
    ["1", 0, "2"],
    ["2", 0, "3"],
    ["2-1", 0, "2-2"],
