  "nodes_info": [
    {
      "id": "1",
      "type": "start",
      "param": {
        "variables": [
          ["case_input", "string"]
        ]
      }
    },
    {
      "id": "2",
      "type": "code",
      "param": {
        "variables": [
          ["input_code", ["case_input", "1"]]
        ],
        "outputs": [
          ["validated_code", "string"],
          ["is_valid", "boolean"]
        ],
        "code": "import ast\n\ndef main(input_code: str):\n    try:\n        # Try to parse the code to check syntax\n        ast.parse(input_code)\n        return {\n            \"validated_code\": input_code,\n            \"is_valid\": True\n        }\n    except SyntaxError as e:\n        return {\n            \"validated_code\": f\"# Invalid code syntax: {str(e)}\\n{input_code}\",\n            \"is_valid\": False\n        }\n    except Exception as e:\n        return {\n            \"validated_code\": f\"# Error validating code: {str(e)}\\n{input_code}\",\n            \"is_valid\": False\n        }"
      }
    },
    {
      "id": "3",
      "type": "llm",
      "param": {
        "system": "You are a Python code executor. Your task is to execute the provided Python code and return both the code and its execution result. If there are any runtime errors, include them in the result.",
        "user": "Execute the following Python code and return both the code and its result:\n\n{{#2.validated_code#}}\n\nFirst, output the Python code as is, then execute it and show the result. Format your response clearly separating the code and its execution result."
      }
    },
    {
      "id": "4",
      "type": "end",
      "param": {
        "outputs": [
          ["python_code", ["validated_code", "2"]],
          ["result", ["text", "3"]]
        ]
      }
    }
  ],
  "edges": [
    ["1", 0, "2"],
    ["2", 0, "3"],
    ["3", 0, "4"]
  ]
}

