{
  "nodes_info": [
    {
      "id": "1",
      "type": "start",
      "param": {
        "variables": [
          ["contract", "file"],
          ["apart", "string"],
          ["workfield", "string"],
          ["attention", "string"]
        ]
      }
    },
    {
      "id": "2",
      "type": "document-extractor",
      "param": {
        "variable_selector": ["contract", "1"]
      }
    },
    {
      "id": "3",
      "type": "llm",
      "param": {
        "system": "You are a legal expert specializing in contract review. Your task is to convert general concerns into specific contract review checkpoints.",
        "user": "Based on the work field '{{#1.workfield#}}' and these specific concerns: '{{#1.attention#}}', generate 5-8 specific contract review checkpoints that should be examined. Format your response as a clear list."
      }
    },
    {
      "id": "4",
      "type": "parameter-extractor",
      "param": {
        "query": ["text", "2"],
        "parameters": [
          ["Key parties in the contract", "parties", "array[string]"],
          ["Main obligations of each party", "obligations", "array[string]"],
          ["Payment terms and amounts", "payments", "array[string]"],
          ["Duration and termination conditions", "terms", "array[string]"],
          ["Liability and indemnification clauses", "liabilities", "array[string]"]
        ],
        "instruction": "Extract the following information from the contract text:\n1. Key parties involved\n2. Main obligations of each party\n3. Payment terms\n4. Contract duration and termination conditions\n5. Liability clauses\n\nFocus on details relevant to {{#1.workfield#}} in the {{#1.apart#}}'s interest."
      }
    },
    {
      "id": "5",
      "type": "llm",
      "param": {
        "system": "You are a senior legal counsel conducting a comprehensive contract risk review. Your goal is to maximize the interests of '{{#1.apart#}}' while considering industry standards in '{{#1.workfield#}}'.",
        "user": "Review the contract text:\n{{#2.text#}}\n\nCheckpoints to consider:\n{{#3.text#}}\n\nKey contract elements:\nParties: {{#4.parties#}}\nObligations: {{#4.obligations#}}\nPayments: {{#4.payments#}}\nTerms: {{#4.terms#}}\nLiabilities: {{#4.liabilities#}}\n\nProvide a detailed risk assessment and specific improvement suggestions that:\n1. Identify potential risks to {{#1.apart#}}\n2. Highlight unfavorable clauses\n3. Suggest concrete modifications\n4. Consider {{#1.workfield#}} industry practices"
      }
    },
    {
      "id": "6",
      "type": "template-transform",
      "param": {
        "variables": [
          ["analysis", ["text", "5"]],
          ["apart", ["apart", "1"]],
          ["workfield", ["workfield", "1"]]
        ],
        "template": "# Contract Risk Review for {{apart}}\n\n## Work Field\n{{workfield}}\n\n## Risk Assessment and Improvement Suggestions\n{{analysis}}\n\n---\n*This review was conducted to maximize {{apart}}'s interests while considering industry standards.*"
      }
    },
    {
      "id": "7",
      "type": "end",
      "param": {
        "outputs": [
          ["result", ["output", "6"]]
        ]
      }
    }
  ],
  "edges": [
    ["1", 0, "2"],
    ["1", 0, "3"],
    ["1", 0, "4"],
    ["2", 0, "5"],
    ["3", 0, "5"],
    ["4", 0, "5"],
    ["5", 0, "6"],
    ["6", 0, "7"]
  ]
}

