        "code": "def main(resumes: list, classifications: list):\n    # Create pairs of resumes and their classifications\n    paired_data = list(zip(resumes, classifications))\n    \n    # Find the first resume in each category\n    accountant_resumes = [resume for resume, category in paired_data if category == 'ACCOUNTANT']\n    arts_resumes = [resume for resume, category in paired_data if category == 'ARTS']\n    sales_resumes = [resume for resume, category in paired_data if category == 'SALES']\n    teacher_resumes = [resume for resume, category in paired_data if category == 'TEACHER']\n    \n    # Select the first resume in each category as the \"best\"\n    best_accountant = accountant_resumes[0] if accountant_resumes else None\n    best_arts = arts_resumes[0] if arts_resumes else None\n    best_sales = sales_resumes[0] if sales_resumes else None\n    best_teacher = teacher_resumes[0] if teacher_resumes else None\n    \n    return {\n        'best_accountant': best_accountant,\n        'best_arts': best_arts,\n        'best_sales': best_sales,\n        'best_teacher': best_teacher\n    }"
